  v := p_data->>k;
  if spec->k->>'kind'='visibility' and v not in ('true','false') then return false; end if;
  if jsonb_typeof(p_data->k) is distinct from 'string' or (not (spec->k->>'optional')::boolean and length(btrim(v))=0) or length(v)>(spec->k->>'max')::integer then return false; end if;
  if spec->k->>'kind'='link' and v !~ '^/($|#(route|booking|destinations)$|(tour|live|explore|book|credits|admin|faq)(#(faq|timetable|centre|castle|lake|bridge))?$|explore/(centre|castle|lake|bridge)$)' then return false; end if;
  if spec->k->>'kind'='image' and v !~ '^/images/[a-zA-Z0-9/_-]+[.](webp|png|jpg|jpeg|avif)$' and v !~ '^https://[a-z0-9-]+[.]supabase[.]co/storage/v1/object/public/website-media/[a-f0-9-]+/[a-f0-9-]+[.](webp|png|jpg|avif)$' then return false; end if;
  if spec->k->>'kind'='external' and v<>'' and (v ~ '^https://[^/?#]*@' or v !~ '^https://[^/@[:space:]<>\\]+([/:?#]|$)' or v ~ '[[:space:]<>\\]') then return false; end if;
  if spec->k->>'kind'='publication' and v not in ('published','unpublished') then return false; end if;
 end loop;
 if p_data->>'hero.desktopPosition' not in ('left top','center top','right top','left center','center center','right center','left bottom','center bottom','right bottom') or p_data->>'hero.mobilePosition' not in ('left top','center top','right top','left center','center center','right center','left bottom','center bottom','right bottom') then return false; end if;
