 if (p_data->>'legal.privacy.status'='published' and length(btrim(p_data->>'legal.privacy.text'))=0) or (p_data->>'legal.terms.status'='published' and length(btrim(p_data->>'legal.terms.text'))=0) then return false; end if;
 return true;
